contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(c).balance >= amount);

        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint cBalAfter = address(c).balance;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        assert(
            cBalAfter == cBalBefore - amount && address(this).balance == balBefore + amount && ownerAfter == ownerBefore
        );
    }

    receive() external payable {}
}

